INSERT OR IGNORE INTO stories (id, date, month, summary_en, html_en, source_url, published) VALUES ('2025-10-06-costa-rica-tribu-cr-launches', '2025-10-06', '2025-10', 'Costa Rica''s Ministerio de Hacienda activated TRIBU-CR, a new integrated tax platform, on 6 October 2025 -- retiring the old free ATV invoicing tool and launching TICO FACTURA in its place, after migrating over 883 million records. It''s the first of nine planned phases, with full rollout targeted for 2027.', '<h3>🇨🇷 Costa Rica launches TRIBU-CR, replacing its ATV tax platform</h3>
<p>At 9:00 a.m. on Monday, 6 October 2025, Costa Rica''s Ministerio de Hacienda activated TRIBU-CR (Sistema Integrado de Administración Tributaria), a new integrated tax platform intended to eventually replace the long-running Administración Tributaria Virtual (ATV) system entirely. Hacienda retired the old free ATV invoicing tool the evening before and launched a new free e-invoicing tool, TICO FACTURA, at the same time -- moving more than 883 million records in the days beforehand.</p>
<p>Costa Rica''s e-invoicing mandate itself hasn''t changed -- Comprobantes Electrónicos have been required for essentially all VAT taxpayers since Resolution DGT-R-012-2018 completed its staggered rollout in November 2018. What''s changing is the infrastructure businesses use to register, file, and (for smaller taxpayers) invoice for free.</p>
<p>TRIBU-CR''s launch is Phase 1 of a planned nine-phase, 28-module rollout, with full completion targeted for 2027 -- a multi-year transition rather than a single cutover. Businesses that relied on Hacienda''s free ATV invoicing tool should confirm they''ve migrated cleanly to TICO FACTURA, and third-party e-invoicing providers should confirm their integrations point at the new platform.</p>', 'https://www.hacienda.go.cr/AvisosTRIBU-CR.html', 1);
INSERT OR IGNORE INTO story_countries (story_id, country_id) SELECT '2025-10-06-costa-rica-tribu-cr-launches', id FROM countries WHERE name_en = 'Costa Rica';
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2025-10-06-costa-rica-tribu-cr-launches', 'en', 'Costa Rica launches TRIBU-CR, replacing its ATV tax platform', 'Costa Rica''s Ministerio de Hacienda activated TRIBU-CR, a new integrated tax platform, on 6 October 2025 -- retiring the old free ATV invoicing tool and launching TICO FACTURA in its place, after migrating over 883 million records. It''s the first of nine planned phases, with full rollout targeted for 2027.', '<h3>🇨🇷 Costa Rica launches TRIBU-CR, replacing its ATV tax platform</h3>
<p>At 9:00 a.m. on Monday, 6 October 2025, Costa Rica''s Ministerio de Hacienda activated TRIBU-CR (Sistema Integrado de Administración Tributaria), a new integrated tax platform intended to eventually replace the long-running Administración Tributaria Virtual (ATV) system entirely. Hacienda retired the old free ATV invoicing tool the evening before and launched a new free e-invoicing tool, TICO FACTURA, at the same time -- moving more than 883 million records in the days beforehand.</p>
<p>Costa Rica''s e-invoicing mandate itself hasn''t changed -- Comprobantes Electrónicos have been required for essentially all VAT taxpayers since Resolution DGT-R-012-2018 completed its staggered rollout in November 2018. What''s changing is the infrastructure businesses use to register, file, and (for smaller taxpayers) invoice for free.</p>
<p>TRIBU-CR''s launch is Phase 1 of a planned nine-phase, 28-module rollout, with full completion targeted for 2027 -- a multi-year transition rather than a single cutover. Businesses that relied on Hacienda''s free ATV invoicing tool should confirm they''ve migrated cleanly to TICO FACTURA, and third-party e-invoicing providers should confirm their integrations point at the new platform.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2025-10-06-costa-rica-tribu-cr-launches', 'es', 'Costa Rica lanza TRIBU-CR y sustituye su plataforma tributaria ATV', 'El Ministerio de Hacienda de Costa Rica activó TRIBU-CR, una nueva plataforma tributaria integrada, el 6 de octubre de 2025 -- dando de baja la antigua herramienta gratuita de facturación ATV y lanzando en su lugar TICO FACTURA, tras migrar más de 883 millones de registros. Es la primera de nueve fases planeadas, con el despliegue completo previsto para 2027.', '<h3>🇨🇷 Costa Rica lanza TRIBU-CR y sustituye su plataforma tributaria ATV</h3>
<p>A las 9:00 a.m. del lunes 6 de octubre de 2025, el Ministerio de Hacienda de Costa Rica activó TRIBU-CR (Sistema Integrado de Administración Tributaria), una nueva plataforma tributaria integrada que busca sustituir por completo, con el tiempo, al sistema de larga data Administración Tributaria Virtual (ATV). Hacienda dio de baja la antigua herramienta gratuita de facturación ATV la noche anterior y lanzó al mismo tiempo una nueva herramienta gratuita de facturación electrónica, TICO FACTURA -- luego de migrar más de 883 millones de registros en los días previos.</p>
<p>El mandato de facturación electrónica de Costa Rica en sí no cambió -- los Comprobantes Electrónicos son obligatorios para prácticamente todos los contribuyentes del IVA desde que la Resolución DGT-R-012-2018 completó su despliegue escalonado en noviembre de 2018. Lo que cambia es la infraestructura que las empresas usan para inscribirse, declarar y, en el caso de los contribuyentes más pequeños, facturar de forma gratuita.</p>
<p>El lanzamiento de TRIBU-CR corresponde a la Fase 1 de un despliegue planeado en nueve fases y 28 módulos, con la finalización total prevista para 2027 -- una transición que se extenderá varios años, no un cambio puntual. Las empresas que dependían de la herramienta gratuita de facturación ATV de Hacienda deben confirmar que ya migraron correctamente a TICO FACTURA, y los proveedores externos de facturación electrónica deben confirmar que sus integraciones ya apuntan a la nueva plataforma.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2025-10-06-costa-rica-tribu-cr-launches', 'de', 'Costa Rica führt TRIBU-CR ein und löst seine Steuerplattform ATV ab', 'Costa Ricas Ministerio de Hacienda aktivierte am 6. Oktober 2025 TRIBU-CR, eine neue integrierte Steuerplattform -- und stellte dabei das alte kostenlose ATV-Rechnungstool ein, an dessen Stelle TICO FACTURA trat, nachdem zuvor mehr als 883 Millionen Datensätze migriert worden waren. Es ist die erste von neun geplanten Phasen, deren vollständige Umsetzung für 2027 vorgesehen ist.', '<h3>🇨🇷 Costa Rica führt TRIBU-CR ein und löst seine Steuerplattform ATV ab</h3>
<p>Um 9:00 Uhr am Montag, dem 6. Oktober 2025, aktivierte Costa Ricas Ministerio de Hacienda TRIBU-CR (Sistema Integrado de Administración Tributaria), eine neue integrierte Steuerplattform, die das langjährige System Administración Tributaria Virtual (ATV) letztlich vollständig ersetzen soll. Hacienda stellte das alte kostenlose ATV-Rechnungstool am Vorabend ein und startete gleichzeitig ein neues kostenloses E-Rechnungstool, TICO FACTURA -- nachdem in den Tagen zuvor mehr als 883 Millionen Datensätze migriert worden waren.</p>
<p>Costa Ricas E-Rechnungspflicht selbst hat sich nicht geändert -- Comprobantes Electrónicos sind für praktisch alle mehrwertsteuerpflichtigen Personen verpflichtend, seit die Resolution DGT-R-012-2018 ihren gestaffelten Rollout im November 2018 abgeschlossen hat. Was sich ändert, ist die Infrastruktur, mit der Unternehmen sich registrieren, Erklärungen abgeben und -- bei kleineren Steuerpflichtigen -- kostenlos Rechnungen stellen.</p>
<p>Der Start von TRIBU-CR bildet Phase 1 eines geplanten neunphasigen Rollouts mit 28 Modulen; die vollständige Fertigstellung ist für 2027 vorgesehen -- eine mehrjährige Umstellung statt eines einmaligen Wechsels. Unternehmen, die sich auf Haciendas kostenloses ATV-Rechnungstool verlassen haben, sollten prüfen, ob sie sauber zu TICO FACTURA migriert sind, und Drittanbieter von E-Rechnungslösungen sollten bestätigen, dass ihre Integrationen auf die neue Plattform ausgerichtet sind.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2025-10-06-costa-rica-tribu-cr-launches', 'fr', 'Le Costa Rica lance TRIBU-CR et remplace sa plateforme fiscale ATV', 'Le Ministerio de Hacienda du Costa Rica a activé TRIBU-CR, une nouvelle plateforme fiscale intégrée, le 6 octobre 2025 -- retirant l''ancien outil de facturation gratuit ATV et lançant TICO FACTURA à sa place, après avoir migré plus de 883 millions d''enregistrements. Il s''agit de la première de neuf phases prévues, l''achèvement complet étant visé pour 2027.', '<h3>🇨🇷 Le Costa Rica lance TRIBU-CR et remplace sa plateforme fiscale ATV</h3>
<p>À 9h00 le lundi 6 octobre 2025, le Ministerio de Hacienda du Costa Rica a activé TRIBU-CR (Sistema Integrado de Administración Tributaria), une nouvelle plateforme fiscale intégrée destinée à remplacer, à terme, entièrement le système Administración Tributaria Virtual (ATV), en place depuis longtemps. Hacienda a retiré l''ancien outil de facturation gratuit ATV la veille au soir et a lancé simultanément un nouvel outil de facturation électronique gratuit, TICO FACTURA -- après avoir migré plus de 883 millions d''enregistrements dans les jours précédents.</p>
<p>L''obligation de facturation électronique du Costa Rica elle-même n''a pas changé -- les Comprobantes électroniques sont exigés pour la quasi-totalité des contribuables à la TVA depuis que la résolution DGT-R-012-2018 a achevé son déploiement échelonné en novembre 2018. Ce qui change, c''est l''infrastructure que les entreprises utilisent pour s''inscrire, déclarer et, pour les petits contribuables, facturer gratuitement.</p>
<p>Le lancement de TRIBU-CR constitue la phase 1 d''un déploiement prévu en neuf phases et 28 modules, l''achèvement complet étant visé pour 2027 -- une transition pluriannuelle plutôt qu''un basculement unique. Les entreprises qui s''appuyaient sur l''outil de facturation gratuit ATV de Hacienda devraient vérifier qu''elles ont bien migré vers TICO FACTURA, et les prestataires tiers de facturation électronique devraient s''assurer que leurs intégrations pointent désormais vers la nouvelle plateforme.</p>');

INSERT OR IGNORE INTO stories (id, date, month, summary_en, html_en, source_url, published) VALUES ('2026-07-23-costa-rica-invoice-fraud-crackdown', '2026-07-23', '2026-07', 'The Costa Rican government presented a 24-measure tax-enforcement package on 23 July 2026, directly targeting fraudulent "false e-invoice" networks -- proposing new authority to administratively suspend a firm''s e-invoicing rights, and disclosing the first 10 criminal complaints filed that week out of more than 400 ongoing investigations.', '<h3>🇨🇷 Costa Rica unveils 24-measure package targeting fraudulent e-invoicing</h3>
<p>On 23 July 2026, President Laura Fernández, Finance Minister Rodrigo Chaves, and Vice Minister Víctor Julio Carvajal presented a 24-measure package aimed at strengthening tax collection and combating evasion -- with a direct focus on fraudulent electronic invoicing. "False e-invoice" networks, used to under-report tax liability, have become a specific enforcement target as Costa Rica''s Comprobantes Electrónicos system has matured.</p>
<p>Among the proposals: new legal authority letting Hacienda administratively suspend a firm''s e-invoicing rights, rather than relying on a lengthy judicial process to shut down a fraudulent operation. The government also disclosed the first 10 criminal complaints filed that week against fraudulent-invoice networks, out of more than 400 ongoing investigations -- one disclosed case involved over ₡41 million in improperly reduced tax.</p>
<p>This follows a pattern of increasingly visible enforcement in Costa Rica''s e-invoicing system: a June 2024 sweep had already fined 279 taxpayers over ₡253 million for invoice-related non-compliance under Article 85 of the Código de Normas y Procedimientos Tributarios. Businesses connected, even indirectly, to a flagged counterparty should treat a sudden loss of e-invoicing rights as a real operational risk if the proposed administrative-suspension authority is enacted.</p>', 'https://www.infobae.com/costa-rica/2026/07/23/costa-rica-presenta-paquete-de-24-medidas-para-fortalecer-el-cobro-de-impuestos-combatir-la-evasion-y-el-contrabando-sin-crear-nuevos-tributos/', 1);
INSERT OR IGNORE INTO story_countries (story_id, country_id) SELECT '2026-07-23-costa-rica-invoice-fraud-crackdown', id FROM countries WHERE name_en = 'Costa Rica';
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-07-23-costa-rica-invoice-fraud-crackdown', 'en', 'Costa Rica unveils 24-measure package targeting fraudulent e-invoicing', 'The Costa Rican government presented a 24-measure tax-enforcement package on 23 July 2026, directly targeting fraudulent "false e-invoice" networks -- proposing new authority to administratively suspend a firm''s e-invoicing rights, and disclosing the first 10 criminal complaints filed that week out of more than 400 ongoing investigations.', '<h3>🇨🇷 Costa Rica unveils 24-measure package targeting fraudulent e-invoicing</h3>
<p>On 23 July 2026, President Laura Fernández, Finance Minister Rodrigo Chaves, and Vice Minister Víctor Julio Carvajal presented a 24-measure package aimed at strengthening tax collection and combating evasion -- with a direct focus on fraudulent electronic invoicing. "False e-invoice" networks, used to under-report tax liability, have become a specific enforcement target as Costa Rica''s Comprobantes Electrónicos system has matured.</p>
<p>Among the proposals: new legal authority letting Hacienda administratively suspend a firm''s e-invoicing rights, rather than relying on a lengthy judicial process to shut down a fraudulent operation. The government also disclosed the first 10 criminal complaints filed that week against fraudulent-invoice networks, out of more than 400 ongoing investigations -- one disclosed case involved over ₡41 million in improperly reduced tax.</p>
<p>This follows a pattern of increasingly visible enforcement in Costa Rica''s e-invoicing system: a June 2024 sweep had already fined 279 taxpayers over ₡253 million for invoice-related non-compliance under Article 85 of the Código de Normas y Procedimientos Tributarios. Businesses connected, even indirectly, to a flagged counterparty should treat a sudden loss of e-invoicing rights as a real operational risk if the proposed administrative-suspension authority is enacted.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-07-23-costa-rica-invoice-fraud-crackdown', 'es', 'Costa Rica presenta un paquete de 24 medidas contra el fraude en la facturación electrónica', 'El Gobierno de Costa Rica presentó un paquete de 24 medidas de fiscalización tributaria el 23 de julio de 2026, dirigido directamente contra las redes de "facturas falsas" -- proponiendo una nueva potestad para suspender administrativamente el derecho de una empresa a facturar electrónicamente, y revelando las primeras 10 denuncias penales presentadas esa semana de un total de más de 400 investigaciones en curso.', '<h3>🇨🇷 Costa Rica presenta un paquete de 24 medidas contra el fraude en la facturación electrónica</h3>
<p>El 23 de julio de 2026, la presidenta Laura Fernández, el ministro de Hacienda Rodrigo Chaves y el viceministro Víctor Julio Carvajal presentaron un paquete de 24 medidas orientado a fortalecer la recaudación tributaria y combatir la evasión -- con un enfoque directo en el fraude de la facturación electrónica. Las redes de "facturas falsas", utilizadas para subdeclarar la obligación tributaria, se han convertido en un blanco específico de fiscalización a medida que madura el sistema de Comprobantes Electrónicos de Costa Rica.</p>
<p>Entre las propuestas: una nueva potestad legal que permitiría a Hacienda suspender administrativamente el derecho de una empresa a facturar electrónicamente, en lugar de depender de un proceso judicial largo para cerrar una operación fraudulenta. El Gobierno también reveló las primeras 10 denuncias penales presentadas esa semana contra redes de facturas falsas, de un total de más de 400 investigaciones en curso -- uno de los casos divulgados involucró más de ₡41 millones en impuestos indebidamente reducidos.</p>
<p>Esto se suma a un patrón de fiscalización cada vez más visible en el sistema de facturación electrónica de Costa Rica: un operativo de junio de 2024 ya había multado a 279 contribuyentes por más de ₡253 millones por incumplimientos relacionados con facturación bajo el artículo 85 del Código de Normas y Procedimientos Tributarios. Las empresas vinculadas, aunque sea indirectamente, con una contraparte señalada deben considerar la pérdida repentina del derecho a facturar electrónicamente como un riesgo operativo real si se aprueba la potestad de suspensión administrativa propuesta.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-07-23-costa-rica-invoice-fraud-crackdown', 'de', 'Costa Rica stellt 24-Punkte-Paket gegen betrügerische E-Rechnungsstellung vor', 'Die costa-ricanische Regierung stellte am 23. Juli 2026 ein 24-Punkte-Steuervollzugspaket vor, das direkt gegen Netzwerke für "falsche E-Rechnungen" gerichtet ist -- mit einer vorgeschlagenen neuen Befugnis zur administrativen Aussetzung des E-Rechnungsrechts eines Unternehmens und der Offenlegung der ersten 10 in dieser Woche eingereichten Strafanzeigen von mehr als 400 laufenden Ermittlungen.', '<h3>🇨🇷 Costa Rica stellt 24-Punkte-Paket gegen betrügerische E-Rechnungsstellung vor</h3>
<p>Am 23. Juli 2026 stellten Präsidentin Laura Fernández, Finanzminister Rodrigo Chaves und Vizeminister Víctor Julio Carvajal ein 24-Punkte-Paket zur Stärkung der Steuererhebung und Bekämpfung der Steuerhinterziehung vor -- mit einem klaren Fokus auf betrügerische elektronische Rechnungsstellung. Netzwerke für "falsche E-Rechnungen", die zur Untererfassung von Steuerschulden genutzt werden, sind mit zunehmender Reife von Costa Ricas Comprobantes-Electrónicos-System zu einem gezielten Vollzugsziel geworden.</p>
<p>Zu den Vorschlägen zählt eine neue gesetzliche Befugnis, die es Hacienda erlauben würde, das Recht eines Unternehmens zur elektronischen Rechnungsstellung administrativ auszusetzen, statt sich auf ein langwieriges Gerichtsverfahren zur Schließung einer betrügerischen Operation zu verlassen. Die Regierung legte zudem die ersten 10 in dieser Woche eingereichten Strafanzeigen gegen Rechnungsbetrugsnetzwerke offen, von mehr als 400 laufenden Ermittlungen -- ein bekannt gegebener Fall betraf über 41 Millionen ₡ an unrechtmäßig reduzierter Steuer.</p>
<p>Dies folgt einem Muster zunehmend sichtbarer Durchsetzung in Costa Ricas E-Rechnungssystem: Eine Kontrollaktion im Juni 2024 hatte bereits 279 Steuerpflichtige mit Bußgeldern von über ₡253 Millionen wegen rechnungsbezogener Verstöße nach Artikel 85 des Código de Normas y Procedimientos Tributarios belegt. Unternehmen, die auch nur indirekt mit einer auffällig gewordenen Gegenpartei verbunden sind, sollten den plötzlichen Verlust des Rechts zur elektronischen Rechnungsstellung als reales operatives Risiko betrachten, falls die vorgeschlagene Befugnis zur administrativen Aussetzung verabschiedet wird.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-07-23-costa-rica-invoice-fraud-crackdown', 'fr', 'Le Costa Rica dévoile un train de 24 mesures contre la fraude à la facturation électronique', 'Le gouvernement costaricien a présenté un train de 24 mesures de contrôle fiscal le 23 juillet 2026, ciblant directement les réseaux de "fausses factures électroniques" -- proposant un nouveau pouvoir permettant de suspendre administrativement le droit d''une entreprise à facturer électroniquement, et révélant les 10 premières plaintes pénales déposées cette semaine-là sur plus de 400 enquêtes en cours.', '<h3>🇨🇷 Le Costa Rica dévoile un train de 24 mesures contre la fraude à la facturation électronique</h3>
<p>Le 23 juillet 2026, la présidente Laura Fernández, le ministre des Finances Rodrigo Chaves et le vice-ministre Víctor Julio Carvajal ont présenté un train de 24 mesures visant à renforcer le recouvrement fiscal et à lutter contre l''évasion fiscale -- avec un accent direct sur la fraude à la facturation électronique. Les réseaux de « fausses factures électroniques », utilisés pour sous-déclarer l''impôt dû, sont devenus une cible spécifique du contrôle à mesure que le système des Comprobantes électroniques du Costa Rica a mûri.</p>
<p>Parmi les propositions figure un nouveau pouvoir légal permettant à Hacienda de suspendre administrativement le droit d''une entreprise à la facturation électronique, plutôt que de s''appuyer sur une longue procédure judiciaire pour mettre fin à une opération frauduleuse. Le gouvernement a également révélé les 10 premières plaintes pénales déposées cette semaine-là contre des réseaux de fausses factures, sur plus de 400 enquêtes en cours -- l''un des cas révélés portait sur plus de 41 millions de ₡ d''impôt indûment réduit.</p>
<p>Cela s''inscrit dans un schéma de contrôle de plus en plus visible au sein du système de facturation électronique du Costa Rica : une opération menée en juin 2024 avait déjà infligé des amendes à 279 contribuables pour un total de plus de 253 millions de ₡, pour des manquements liés à la facturation en vertu de l''article 85 du Código de Normas y Procedimientos Tributarios. Les entreprises liées, même indirectement, à une contrepartie signalée devraient considérer la perte soudaine du droit à la facturation électronique comme un risque opérationnel réel si le pouvoir de suspension administrative proposé est adopté.</p>');
